mapper.insert:
INSERT INTO behavior_history_item(command_id,behavior_id)
SELECT command_id,value::bigint FROM behavior_history_command,
    jsonb_array_elements_text(manifest_json::jsonb) WHERE command_id=#{id}

mapper.select:
SELECT behavior_id FROM behavior_history_item WHERE command_id=#{id} AND status='WAITING_SOURCE'
AND behavior_id NOT IN #{v}
ORDER BY last_visit,behavior_id LIMIT 1 FOR UPDATE SKIP LOCKED
